// branding.js - Shared assets and image processing
const CAP_LOGO_B64 = "data:image/png;base64,";
const CB_LOGO_B64 = "data:image/png;base64,";
const COMBINED_LOGO_B64 = 'data:image/png;base64,';
const COMBINED_LOGO_WHITE_B64 = 'data:image/png;base64,';


/**
 * Returns the base64 string for the black Combined Artists logo
 */
function getBlackLogo() {
    return (typeof COMBINED_LOGO_B64 !== 'undefined' && COMBINED_LOGO_B64) ? COMBINED_LOGO_B64 : (typeof CAP_LOGO_B64 !== 'undefined' ? CAP_LOGO_B64 : null);
}

/**
 * Returns the base64 string for the white Combined Artists logo
 */
function getWhiteLogo() {
    return (typeof COMBINED_LOGO_WHITE_B64 !== 'undefined' && COMBINED_LOGO_WHITE_B64) ? COMBINED_LOGO_WHITE_B64 : (typeof CAP_LOGO_B64 !== 'undefined' ? CAP_LOGO_B64 : null);
}

/**
 * Helper to get the correct logo based on the current theme
 */
function getCurrentThemeLogo() {
    const isDark = !document.documentElement.classList.contains('light-mode');
    return isDark ? getWhiteLogo() : getBlackLogo();
}

// Export functions to window for global access
window.getBlackLogo = getBlackLogo;
window.getWhiteLogo = getWhiteLogo;
window.getCurrentThemeLogo = getCurrentThemeLogo;
window.CAP_LOGO_B64 = CAP_LOGO_B64;
window.CB_LOGO_B64 = CB_LOGO_B64;
window.COMBINED_LOGO_B64 = COMBINED_LOGO_B64;
window.COMBINED_LOGO_WHITE_B64 = COMBINED_LOGO_WHITE_B64;
